nt n ; 
vi adjList [maxn] ; 
int pos , best ; 

int dp [maxn] ; 
void bfs ( int u ) 
{
    queue <int> q ; 
    memset (dp,-1,sizeof dp) ;
    dp [u] = 0 ; 
    q . push (u) ; 
    while ( !q.empty())
    {
        int u = q.front() ; q.pop() ; 
        for ( auto v : adjList [u] ) 
        {
            if ( dp [v] == -1 ) 
            {
                dp [v] = dp [u] + 1 , q . push (v) ; 
            }
        }
    }
    best = -1 ; 
    for ( int i = 1 ; i <= n ; i ++ ) if ( dp [i] > best ) best = dp [i] , pos = i ; 
}
signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    cin >> n ; 
    for ( int i = 1 ; i < n ; i ++ ) 
    {
        int u , v ; cin >> u >> v ; 
        adjList [u] . pb (v) ; 
        adjList [v] . pb (u) ; 
    }
    bfs (1) , bfs (pos) ; 
    cout << best ; 
    return 0;
}
